'use strict';
const STORE='gc_wellness_v1';
const localStorage=window.gcWellnessStorage;
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
function localDay(date=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Lisbon',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);return ['year','month','day'].map(type=>parts.find(p=>p.type===type).value).join('-');}
function dayOffset(days){const date=new Date();date.setDate(date.getDate()+days);return localDay(date);}
const METRICS=[
 {id:'sleep',name:'Qualidade do sono',hint:'Como dormiste?',labels:['Muito mau','Mau','Razoável','Bom','Muito bom']},
 {id:'freshness',name:'Fadiga',hint:'Como te sentes fisicamente?',labels:['Muito cansado','Cansado','Razoável','Fresco','Muito fresco']},
 {id:'muscles',name:'Dores musculares',hint:'Como estão os teus músculos?',labels:['Muitas dores','Algumas dores','Moderadas','Poucas dores','Sem dores']},
 {id:'stress',name:'Stress',hint:'Como te sentes?',labels:['Muito elevado','Elevado','Moderado','Baixo','Muito baixo']},
 {id:'mood',name:'Disposição',hint:'Como está o teu ânimo?',labels:['Muito baixa','Baixa','Razoável','Boa','Muito boa']}
];
const PSE_LABELS=['Repouso','Muito leve','Leve','Moderado','Algo intenso','Intenso','','Muito intenso','','','Máximo'];
function wellnessTotal(record){const values=METRICS.map(m=>record?.wellness?.[m.id]);return values.every(v=>Number.isInteger(v)&&v>=1&&v<=5)?values.reduce((a,b)=>a+b,0):null;}
function validPSE(record){return record?.pse!==null&&record?.pse!==undefined&&Number.isInteger(record.pse)&&record.pse>=0&&record.pse<=10&&Number.isFinite(record.duration)&&record.duration>=0&&record.duration<=360;}
function loadValue(record){return validPSE(record)?record.pse*record.duration:null;}
const mean=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const format=(value,digits=0)=>value===null||value===undefined?'—':new Intl.NumberFormat('pt-PT',{maximumFractionDigits:digits}).format(value);
function makeSession(team,date=localDay(),type='treino'){return {id:uid(),teamId:team.id,date,type,title:type==='treino'?'Treino de equipa':'Jogo de preparação',duration:type==='treino'?75:40,participants:team.players.map(p=>p.id),roster:structuredClone(team.players),records:{},status:'draft',updatedAt:new Date().toISOString()};}
function seed(){const teams=GCSharedRoster.readTeams(),draft=makeSession(teams[0]);return {version:1,teams,sessions:[draft],currentId:draft.id};}
let state;try{const raw=localStorage.getItem(STORE);state=raw?JSON.parse(raw):seed();if(state.version!==1||!Array.isArray(state.teams)||!Array.isArray(state.sessions))throw Error('Dados incompatíveis');}catch(error){state=seed();}
state.teams=GCSharedRoster.readTeams();
let ui={page:'sessao',stage:'wellness',selected:null,dirty:false,historyTeam:state.teams[0].id,historyPlayer:'all'};
const session=()=>state.sessions.find(s=>s.id===state.currentId&&!s.deleted);
if(!session()){const draft=makeSession(state.teams[0]);state.sessions.push(draft);state.currentId=draft.id;}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));window.gcWellnessPersist?.();$('saveIndicator').textContent='Guardado localmente · '+new Date().toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'});}catch(error){toast('Não foi possível guardar neste navegador. Exporta os registos e verifica o armazenamento.');}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
function discardChanges(){if(!ui.dirty)return true;if(!confirm('Há respostas por guardar. Queres sair sem as guardar?'))return false;ui.dirty=false;return true;}
function selectedPlayer(){const s=session();if(!s.participants.includes(ui.selected))ui.selected=s.participants[0]||null;return s.roster.find(p=>p.id===ui.selected);}
function recordFor(id){return session().records[id]||{};}
function initials(name){return name.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase();}
function selectOptions(select,options,value){select.innerHTML=options.map(([id,label])=>`<option value="${esc(id)}">${esc(label)}</option>`).join('');select.value=value;}
function setPage(page){if(!discardChanges())return;ui.page=page;$('playerProfile').hidden=true;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));for(const p of ['sessao','historico','plantel'])$('page-'+p).hidden=p!==page;if(page==='sessao')renderSession();if(page==='historico')renderHistory();if(page==='plantel')renderRoster();}
function stageComplete(record,stage){return stage==='pse'?validPSE(record):stage==='summary'?wellnessTotal(record)!==null&&validPSE(record):wellnessTotal(record)!==null;}
function renderSession(){
 const s=session(),team=state.teams.find(t=>t.id===s.teamId);document.querySelectorAll('a.return-game,a.brand').forEach(a=>a.href='app.html?equipa='+encodeURIComponent(s.teamId));
 selectOptions($('team'),state.teams.map(t=>[t.id,t.name]),s.teamId);$('sessionType').value=s.type;$('sessionDate').value=s.date;$('sessionTitle').value=s.title;$('sessionDuration').value=s.duration;
 $('sessionCompactTitle').textContent=s.title||'Sessão sem identificação';$('sessionCompactMeta').textContent=team.name+' · '+s.date.split('-').reverse().join('/')+' · '+(s.type==='jogo'?'Jogo':'Treino')+' · '+s.participants.length+' jogadores';$('finishFromEditor').hidden=ui.stage==='summary';
 $('sessionState').textContent=s.status==='saved'?'Concluída':'Rascunho';$('participantCount').textContent=s.participants.length;
 document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.stage===ui.stage)));
 renderPlayerList();$('summaryPanel').hidden=ui.stage!=='summary';$('editorPanel').hidden=ui.stage==='summary';
 if(ui.stage==='summary')renderSummary();else renderForm();
}
function renderPlayerList(){
 const s=session();selectedPlayer();const done=s.participants.filter(id=>stageComplete(s.records[id],ui.stage)).length;$('progressCount').textContent=done+' / '+s.participants.length;
 $('playerList').innerHTML='<label class="player-select-label" for="sessionPlayerSelect">Jogador</label><select id="sessionPlayerSelect">'+s.participants.map(id=>{const p=s.roster.find(p=>p.id===id);return p?'<option value="'+esc(id)+'" '+(id===ui.selected?'selected':'')+'>'+esc(p.name)+(p.isGK?' · GR':'')+' · '+(stageComplete(s.records[id],ui.stage)?'Preenchido':'Por preencher')+'</option>':'';}).join('')+'</select><span class="player-position">'+(s.participants.length?s.participants.indexOf(ui.selected)+1:0)+' de '+s.participants.length+'</span>';
 $('sessionPlayerSelect').onchange=()=>{const id=$('sessionPlayerSelect').value;if(!discardChanges()){$('sessionPlayerSelect').value=ui.selected;return;}ui.selected=id;if(ui.stage==='summary')ui.stage='wellness';renderSession();};
}
function renderForm(){
 const p=selectedPlayer(),s=session();if(!p){$('athleteForm').hidden=true;$('athleteName').textContent='Seleciona os participantes';return;}
 $('athleteForm').hidden=false;$('athleteName').textContent=p.name;$('athleteAvatar').textContent=initials(p.name);$('athleteMeta').textContent=(p.isGK?'Guarda-redes':'Jogador de campo')+' · '+(s.type==='jogo'?'Jogo':'Treino');
 $('formEyebrow').textContent=ui.stage==='wellness'?'BEM-ESTAR · ANTES':'PSE · DEPOIS';
 const r=recordFor(p.id);$('wellnessFields').hidden=ui.stage!=='wellness';$('pseFields').hidden=ui.stage!=='pse';$('playerDuration').required=ui.stage==='pse';
 $('editorPanel').classList.toggle('quick-wellness',ui.stage==='wellness');
 const shortQuestions={sleep:'Dormiste bem?',freshness:'Tens energia?',muscles:'Como estão os músculos?',stress:'Como está o teu nível de stress?',mood:'Estás bem-disposto?'};
 const ends={sleep:['Muito mal','Muito bem'],freshness:['Muito cansado','Muito fresco'],muscles:['Muitas dores','Sem dores'],stress:['Muito elevado','Muito baixo'],mood:['Nada','Muito']};
 $('wellnessFields').innerHTML='<div class="quick-intro"><strong>Cinco toques. Como te sentes hoje?</strong><span>1 = menos favorável · 5 = mais favorável</span></div>'+METRICS.map(m=>`<fieldset class="wellness-question quick-question"><legend>${m.name}</legend><div class="question-heading"><strong>${shortQuestions[m.id]}</strong></div><div class="quick-answer"><div class="rating-options">${m.labels.map((label,i)=>`<label class="rating-option"><input type="radio" name="${m.id}" value="${i+1}" ${r.wellness?.[m.id]===i+1?'checked':''} ${ui.stage==='wellness'?'required':''} aria-label="${m.name}: ${i+1} · ${label}"><span class="rating-body"><b>${i+1}</b></span></label>`).join('')}</div><div class="quick-ends"><span>${ends[m.id][0]}</span><span>${ends[m.id][1]}</span></div></div></fieldset>`).join('');
 $('pseOptions').innerHTML=Array.from({length:11},(_,i)=>`<label class="pse-option"><input type="radio" name="pse" value="${i}" ${r.pse===i?'checked':''} ${ui.stage==='pse'?'required':''} aria-label="PSE ${i}${PSE_LABELS[i]?' · '+PSE_LABELS[i]:''}"><span>${i}</span></label>`).join('');
 // Os campos do outro momento não participam na validação do formulário.
 $('wellnessFields').querySelectorAll('input').forEach(input=>input.disabled=ui.stage!=='wellness');$('pseOptions').querySelectorAll('input').forEach(input=>input.disabled=ui.stage!=='pse');$('playerDuration').disabled=ui.stage!=='pse';
 $('playerDuration').value=r.duration??s.importedMinutes?.[p.id]??(s.sourceMatchId?'':s.duration);const durationHelp=$('playerDuration').closest('.load-block').querySelector('.micro');durationHelp.textContent=s.sourceMatchId?'Minutos jogados importados do Game Control. Podes corrigir a duração considerada para a PSE.':'Confirma o tempo considerado para este jogador. Não é importado automaticamente do jogo.';$('playerNote').value=ui.stage==='wellness'?r.wellnessNote||'':r.pseNote||'';
 $('recordHint').textContent=stageComplete(r,ui.stage)?'Resposta guardada · podes corrigir.':ui.stage==='wellness'?'Escolhe uma resposta em cada linha.':'Regista a resposta do jogador.';
 $('notesToggle').hidden=ui.stage!=='wellness';$('notesToggle').setAttribute('aria-expanded',r.wellnessNote?'true':'false');$('notesArea').hidden=ui.stage==='wellness'&&!r.wellnessNote;
 $('quickMode').hidden=ui.stage!=='wellness';
 const index=s.participants.indexOf(p.id);$('previousPlayer').disabled=index===0;$('nextPlayer').disabled=index===s.participants.length-1;
 $('savePlayer').innerHTML=index===s.participants.length-1?'Guardar resposta <span>✓</span>':'Guardar e próximo <span>→</span>';updateLoadPreview();ui.dirty=false;
}
function updateLoadPreview(){const chosen=document.querySelector('input[name="pse"]:checked'),minutes=$('playerDuration').value;const valid=chosen&&minutes!==''&&Number.isFinite(Number(minutes))&&Number(minutes)>=0&&Number(minutes)<=360;$('loadPreview').textContent=valid?format(Number(chosen.value)*Number(minutes)):'—';$('loadFormula').textContent=valid?chosen.value+' × '+minutes+' min · UA':'PSE × minutos · UA';}
function movePlayer(direction){if(!discardChanges())return;const s=session(),index=s.participants.indexOf(ui.selected),next=s.participants[index+direction];if(next){ui.selected=next;renderSession();}}
function sessionStats(s,playerId='all'){
 const ids=playerId==='all'?s.participants:s.participants.filter(id=>id===playerId),records=ids.map(id=>s.records[id]||{}),wellness=records.map(wellnessTotal).filter(v=>v!==null),pse=records.filter(validPSE);
 return {count:ids.length,wellnessCount:wellness.length,pseCount:pse.length,wellness:mean(wellness),pse:mean(pse.map(r=>r.pse)),load:mean(pse.map(loadValue)),totalLoad:pse.reduce((n,r)=>n+loadValue(r),0)};
}
function metric(value,label,detail=''){return `<div class="metric"><strong>${value}</strong><span>${esc(label)}</span>${detail?`<small>${esc(detail)}</small>`:''}</div>`;}
function renderSummary(){
 const s=session(),stats=sessionStats(s);$('summaryMetrics').innerHTML=metric(stats.wellnessCount+'/'+stats.count,'Bem-estar preenchido')+metric(stats.pseCount+'/'+stats.count,'PSE preenchida')+metric(format(stats.wellness,1),'Bem-estar médio','de 25 pontos')+metric(format(stats.load),'Carga média','UA · só respostas preenchidas');
 $('summaryRows').innerHTML=s.participants.map(id=>{const p=s.roster.find(p=>p.id===id),r=s.records[id]||{},w=wellnessTotal(r),complete=w!==null&&validPSE(r);return `<tr><td>${esc(p?.name||id)}<small>${p?.isGK?'Guarda-redes':'Campo'}</small></td><td>${w===null?'—':w+' / 25'}</td><td>${validPSE(r)?r.pse:'—'}</td><td>${validPSE(r)?r.duration:'—'}</td><td>${format(loadValue(r))}</td><td><button data-edit-player="${esc(id)}"><span class="status-pill ${complete?'done':''}">${complete?'Completo':'Por preencher'} · editar</span></button></td></tr>`;}).join('');
 $('summaryRows').querySelectorAll('[data-edit-player]').forEach(b=>b.onclick=()=>{ui.selected=b.dataset.editPlayer;ui.stage=wellnessTotal(recordFor(ui.selected))===null?'wellness':'pse';renderSession();});
}
function savePlayerRecord(event){
 event.preventDefault();const s=session(),p=selectedPlayer();if(!p)return;const previous=recordFor(p.id),record={...previous};
 if(ui.stage==='wellness'){
  record.wellness=Object.fromEntries(METRICS.map(m=>[m.id,Number(document.querySelector('input[name="'+m.id+'"]:checked')?.value)]));if(wellnessTotal(record)===null){toast('Responde aos cinco indicadores antes de guardar.');return;}record.wellnessNote=$('playerNote').value.trim();
 }else{
  const selected=document.querySelector('input[name="pse"]:checked');record.pse=selected?Number(selected.value):null;record.duration=$('playerDuration').value===''?null:Number($('playerDuration').value);if(!validPSE(record)){toast('Escolhe a PSE e uma duração entre 0 e 360 minutos.');return;}record.pseNote=$('playerNote').value.trim();
 }
 s.records[p.id]=record;s.updatedAt=new Date().toISOString();ui.dirty=false;persist();toast('Resposta de '+p.name+' guardada.');
 const next=s.participants[s.participants.indexOf(p.id)+1];if(next)ui.selected=next;renderSession();
}
function modal(title){const dialog=document.createElement('dialog');const heading=document.createElement('div');heading.className='dialog-heading';const h=document.createElement('h2');h.textContent=title;const close=document.createElement('button');close.type='button';close.textContent='✕';close.setAttribute('aria-label','Fechar');close.onclick=()=>dialog.close();heading.append(h,close);dialog.appendChild(heading);dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.appendChild(dialog);return dialog;}
function chooseParticipants(){
 if(!discardChanges())return;const s=session(),team=state.teams.find(t=>t.id===s.teamId),dialog=modal('Participantes da sessão');
 const note=document.createElement('p');note.className='micro';note.textContent='Escolhe quem participa. Retirar um jogador da lista não apaga as respostas já guardadas.';dialog.appendChild(note);
 const toolbar=document.createElement('div');toolbar.className='dialog-actions';toolbar.style.marginTop='5px';const all=document.createElement('button');all.className='button';all.textContent='Selecionar todos';const none=document.createElement('button');none.className='button';none.textContent='Limpar seleção';toolbar.append(all,none);dialog.appendChild(toolbar);
 const available=[...team.players.map(p=>s.roster.find(old=>old.id===p.id)||p),...s.roster.filter(p=>!team.players.some(x=>x.id===p.id))];
 const list=document.createElement('div');list.innerHTML=available.map(p=>`<label class="participant-row"><input type="checkbox" value="${esc(p.id)}" ${s.participants.includes(p.id)?'checked':''}>${esc(p.name)}<small>${p.isGK?'GR':'Campo'}</small></label>`).join('');dialog.appendChild(list);all.onclick=()=>list.querySelectorAll('input').forEach(i=>i.checked=true);none.onclick=()=>list.querySelectorAll('input').forEach(i=>i.checked=false);
 const footer=document.createElement('div');footer.className='dialog-actions';const save=document.createElement('button');save.className='button primary';save.textContent='Aplicar participantes';save.onclick=()=>{const ids=[...list.querySelectorAll('input:checked')].map(i=>i.value);if(!ids.length){toast('Seleciona pelo menos um participante.');return;}s.participants=ids;s.roster=available;s.updatedAt=new Date().toISOString();persist();dialog.close();renderSession();};footer.appendChild(save);dialog.appendChild(footer);dialog.showModal();
}
function finishSession(){
 if(!discardChanges())return;const s=session(),stats=sessionStats(s);
 if(!stats.wellnessCount&&!stats.pseCount){toast('Regista pelo menos uma resposta antes de concluir.');return;}
 if((stats.wellnessCount<stats.count||stats.pseCount<stats.count)&&!confirm('Há respostas por preencher. Queres concluir e guardar a sessão mesmo assim? Podes completá-la mais tarde.'))return;
 s.status='saved';s.updatedAt=new Date().toISOString();persist();ui.historyTeam=s.teamId;$('historyTeam').value=s.teamId;toast('Sessão guardada no histórico.');setPage('historico');
}
function filteredSessions(){const from=$('historyFrom').value,to=$('historyTo').value,type=$('historyType').value;return state.sessions.filter(s=>!s.deleted&&s.teamId===ui.historyTeam&&(type==='all'||s.type===type)&&(!from||s.date>=from)&&(!to||s.date<=to)&&(ui.historyPlayer==='all'||s.participants.includes(ui.historyPlayer))).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt));}
function renderHistory(){
 renderCalendar();
 renderWeeklyPanel();
 selectOptions($('historyTeam'),state.teams.map(t=>[t.id,t.name]),ui.historyTeam);
 const team=state.teams.find(t=>t.id===ui.historyTeam),roster=new Map(team.players.map(p=>[p.id,p]));state.sessions.filter(s=>s.teamId===team.id).forEach(s=>s.roster.forEach(p=>{if(!roster.has(p.id))roster.set(p.id,p);}));
 if(ui.historyPlayer!=='all'&&!roster.has(ui.historyPlayer))ui.historyPlayer='all';selectOptions($('historyPlayer'),[['all','Todos os jogadores'],...[...roster.values()].map(p=>[p.id,p.name])],ui.historyPlayer);
 const sessions=filteredSessions(),allRecords=sessions.flatMap(s=>(ui.historyPlayer==='all'?s.participants:s.participants.filter(id=>id===ui.historyPlayer)).map(id=>s.records[id]||{})),w=allRecords.map(wellnessTotal).filter(v=>v!==null),pse=allRecords.filter(validPSE);
 $('historyMetrics').innerHTML=metric(sessions.length,'Sessões no período')+metric(format(mean(w),1),'Bem-estar médio','de 25 · '+w.length+' respostas')+metric(format(mean(pse.map(r=>r.pse)),1),'PSE média',pse.length+' respostas')+metric(format(pse.reduce((sum,r)=>sum+loadValue(r),0)),'Carga acumulada · UA',ui.historyPlayer==='all'?'Soma de todos os jogadores':'Soma deste jogador');
 $('chartTitle').textContent=ui.historyPlayer==='all'?'Carga média por sessão':'Carga por sessão · '+roster.get(ui.historyPlayer).name;
 const chartData=sessions.map(s=>({s,stats:sessionStats(s,ui.historyPlayer)})).filter(x=>x.stats.load!==null).reverse().slice(-14),max=Math.max(...chartData.map(x=>x.stats.load),1);
 $('historyChart').innerHTML=chartData.length?chartData.map(({s,stats})=>`<button class="chart-column" data-open-session="${esc(s.id)}" title="${esc(s.title)} · ${format(stats.load)} UA"><strong>${format(stats.load)}</strong><span class="bar ${s.type==='jogo'?'jogo':''}" style="height:${Math.max(4,stats.load/max*130)}px"></span><span>${s.date.slice(8)}/${s.date.slice(5,7)}</span><small>${s.type==='jogo'?'Jogo':'Treino'}</small></button>`).join(''):'<div class="empty-state">Ainda não existem registos de PSE neste período.</div>';
 $('historyList').innerHTML=sessions.length?sessions.map(s=>{const stats=sessionStats(s,ui.historyPlayer),month=new Date(s.date+'T12:00:00').toLocaleDateString('pt-PT',{month:'short'});return `<div class="session-row"><div class="date-tile">${s.date.slice(8)}<small>${esc(month)}</small></div><div class="session-row-main"><h3>${esc(s.title||'Sem identificação')}</h3><p>${s.type==='jogo'?'Jogo':'Treino'} · ${s.participants.length} participantes · ${s.status==='saved'?'Concluída':'Rascunho'}</p></div><div class="mini-stat">${format(stats.wellness,1)}<small>bem-estar / 25</small></div><div class="mini-stat">${format(stats.load)}<small>carga média · UA</small></div><button class="button quiet" data-open-session="${esc(s.id)}">Consultar →</button></div>`;}).join(''):'<div class="empty-state">Sem sessões para estes filtros. Altera a equipa ou as datas.</div>';
 document.querySelectorAll('[data-open-session]').forEach(b=>b.onclick=()=>openSession(b.dataset.openSession));
}
function openSession(id){if(!discardChanges())return;const s=state.sessions.find(s=>s.id===id);if(!s)return;state.currentId=id;ui.selected=s.participants[0];ui.stage='summary';persist();setPage('sessao');}
function renderRoster(){selectOptions($('rosterTeam'),state.teams.map(t=>[t.id,t.name]),ui.rosterTeam||session().teamId);ui.rosterTeam=$('rosterTeam').value;document.querySelectorAll('a.return-game,a.brand').forEach(a=>a.href='app.html?equipa='+encodeURIComponent(ui.rosterTeam));$('manageRosterLink').href='app.html?gerir=1&equipa='+encodeURIComponent(ui.rosterTeam);const team=state.teams.find(t=>t.id===ui.rosterTeam);$('rosterCards').innerHTML=team.players.map(p=>`<button class="roster-card player-profile-card" data-profile-player="${esc(p.id)}"><span class="avatar">${esc(initials(p.name))}</span><div><h3>${esc(p.name)}</h3><p>${p.isGK?'Guarda-redes':'Jogador de campo'}</p><small>Histórico e gráficos →</small></div></button>`).join('');$('rosterCards').querySelectorAll('[data-profile-player]').forEach(b=>b.onclick=()=>openPlayerProfile(b.dataset.profilePlayer));$('playerProfile').hidden=true;}
function csvRows(){const sessions=filteredSessions(),rows=[['Data','Equipa','Sessão','Tipo','Estado','Jogador','Sono','Fadiga (5=fresco)','Dores (5=sem dores)','Stress (5=baixo)','Disposição','Bem-estar (5–25)','PSE (0–10)','Duração (min)','Carga (UA)','Observações antes','Observações depois']];for(const s of sessions)for(const id of s.participants){if(ui.historyPlayer!=='all'&&id!==ui.historyPlayer)continue;const r=s.records[id]||{},p=s.roster.find(p=>p.id===id);rows.push([s.date,state.teams.find(t=>t.id===s.teamId)?.name,s.title,s.type,s.status==='saved'?'Concluída':'Rascunho',p?.name,...METRICS.map(m=>r.wellness?.[m.id]??''),wellnessTotal(r)??'',validPSE(r)?r.pse:'',validPSE(r)?r.duration:'',loadValue(r)??'',r.wellnessNote||'',r.pseNote||'']);}return rows;}
function exportCSV(){const rows=csvRows();if(rows.length===1){toast('Não existem registos para exportar com estes filtros.');return;}const csv='\ufeff'+rows.map(row=>row.map(value=>{let text=String(value??'');if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='GameControl-Wellness-PSE-'+localDay()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exportado com os filtros atuais.');}
function methodHelp(){const dialog=modal('Como ler os registos');const content=document.createElement('div');content.className='method-copy';content.innerHTML='<p><strong>Antes da sessão:</strong> cinco indicadores de bem-estar, cada um de 1 a 5. Em todos, 5 corresponde à resposta mais favorável. O total é a soma (5–25); não é uma previsão de lesão ou uma autorização para jogar.</p><p><strong>Depois:</strong> o próprio jogador indica a PSE global da sessão de 0 a 10. A duração é confirmada individualmente, com a mesma convenção entre sessões.</p><p><strong>Carga da sessão = PSE × duração (minutos).</strong> Exemplo: 6 × 75 = 450 unidades arbitrárias (UA). A duração de referência não substitui a confirmação individual.</p><p>Na equipa, as médias usam apenas respostas preenchidas. A carga acumulada soma as cargas registadas para os filtros escolhidos. Ausência de resposta é diferente de zero.</p><p>Na literatura consultada, a PSE da sessão é recolhida após um intervalo depois do exercício, frequentemente 20–30 minutos. Neste protótipo não há lembretes nem aplicação automática de horários.</p><p>Referências: <a href="https://www.frontiersin.org/journals/neuroscience/articles/10.3389/fnins.2017.00612/full" target="_blank" rel="noopener noreferrer">método session-RPE</a> · <a href="https://link.springer.com/article/10.1186/s13102-023-00743-y" target="_blank" rel="noopener noreferrer">questionário de bem-estar e carga</a>.</p><p>Os registos pertencem à tua conta e sincronizam quando a indicação no topo confirma o envio. As equipas e plantéis são geridos no Game Control.</p>';dialog.appendChild(content);dialog.showModal();}
