function monthBounds(month){const [year,m]=month.split('-').map(Number);return {start:month+'-01',end:month+'-'+String(new Date(year,m,0).getDate()).padStart(2,'0')};}
function showCalendarMonth(month){ui.calendarMonth=month;const bounds=monthBounds(month);$('historyFrom').value=bounds.start;$('historyTo').value=bounds.end;renderHistory();}
function moveCalendar(delta){const [year,m]=(ui.calendarMonth||localDay().slice(0,7)).split('-').map(Number),d=new Date(year,m-1+delta,1);showCalendarMonth(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}
function renderCalendar(){
 const month=ui.calendarMonth||localDay().slice(0,7);ui.calendarMonth=month;
 const [year,m]=month.split('-').map(Number),first=new Date(year,m-1,1),offset=(first.getDay()+6)%7,days=new Date(year,m,0).getDate();
 const title=first.toLocaleDateString('pt-PT',{month:'long',year:'numeric'});$('calendarMonth').textContent=title.charAt(0).toUpperCase()+title.slice(1);
 const sessions=filteredSessions().filter(s=>s.date.slice(0,7)===month);const grouped=new Map();for(const s of sessions){if(!grouped.has(s.date))grouped.set(s.date,[]);grouped.get(s.date).push(s);}
 let html=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(day=>'<div class="calendar-weekday">'+day+'</div>').join('');
 const cells=Math.ceil((offset+days)/7)*7;
 for(let cell=0;cell<cells;cell++){const day=cell-offset+1;if(day<1||day>days){html+='<div class="calendar-day outside" aria-hidden="true"></div>';continue;}
 const date=month+'-'+String(day).padStart(2,'0'),events=grouped.get(date)||[];
 html+='<div class="calendar-day'+(date===localDay()?' is-today':'')+'"><span class="calendar-date">'+day+'</span><div class="calendar-events">'+events.map(s=>'<button class="calendar-event '+(s.type==='jogo'?'match':'training')+'" data-open-session="'+esc(s.id)+'" aria-label="'+esc((s.type==='jogo'?'Jogo':'Treino')+' · '+s.title+' · '+date)+'"><strong>'+(s.type==='jogo'?'Jogo':'Treino')+'</strong><span>'+esc(s.title||'Sem identificação')+'</span><small>'+(s.status==='saved'?'Concluída':'Rascunho')+'</small></button>').join('')+'</div></div>';
 }
 $('sessionCalendar').innerHTML=html;$('calendarEmpty').hidden=sessions.length>0;
}

