function playerSessions(teamId,playerId,from='',to='',type='all'){
 return state.sessions.filter(s=>!s.deleted&&s.teamId===teamId&&s.participants.includes(playerId)&&(!from||s.date>=from)&&(!to||s.date<=to)&&(type==='all'||s.type===type)).sort((a,b)=>a.date.localeCompare(b.date)||a.updatedAt.localeCompare(b.updatedAt));
}
