function individualChart(sessions,playerId,kind,label,max,color){
 const points=sessions.map(s=>({s,value:kind.startsWith('metric:')?(s.records[playerId]?.wellness?.[kind.slice(7)]??null):kind==='wellness'?wellnessTotal(s.records[playerId]):kind==='pse'?(validPSE(s.records[playerId])?s.records[playerId].pse:null):loadValue(s.records[playerId])}));
 if(!points.some(p=>p.value!==null))return `<section class="panel individual-chart"><h2>${label}</h2><div class="empty-state">Ainda sem respostas para este gráfico.</div></section>`;
 const width=600,height=205,left=40,right=18,top=20,bottom=40,plotH=height-top-bottom,x=i=>left+(points.length===1?(width-left-right)/2:i*(width-left-right)/(points.length-1)),y=value=>top+(max-value)/max*plotH;
 let svg='';for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${left}" y1="${y(v)}" x2="${width-right}" y2="${y(v)}" stroke="rgba(167,190,210,.12)"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end" fill="#9eafbd" font-size="10">${format(v,1)}</text>`;}
 let previous=null;points.forEach((point,i)=>{if(point.value===null){previous=null;return;}if(previous!==null)svg+=`<line x1="${x(previous)}" y1="${y(points[previous].value)}" x2="${x(i)}" y2="${y(point.value)}" stroke="${color}" stroke-width="2.5"/>`;svg+=`<g class="chart-point" role="button" tabindex="0" aria-label="${esc(point.s.date+' · '+point.s.title+' · '+label+': '+format(point.value))}" data-point-date="${esc(point.s.date)}" data-point-session="${esc(point.s.title)}" data-point-value="${esc(format(point.value)+(kind.startsWith('metric:')?' / 5':kind==='wellness'?' / 25':kind==='pse'?' / 10':' UA'))}" data-point-type="${point.s.type==='jogo'?'Jogo':'Treino'}"><circle class="point-hit" cx="${x(i)}" cy="${y(point.value)}" r="14" fill="transparent"/><circle class="point-dot" cx="${x(i)}" cy="${y(point.value)}" r="4" fill="${color}" pointer-events="none"/></g>`;previous=i;});
 points.forEach((point,i)=>{if(i===0||i===points.length-1||points.length<=7)svg+=`<text x="${x(i)}" y="${height-14}" text-anchor="middle" fill="#9eafbd" font-size="10">${point.s.date.slice(8)}/${point.s.date.slice(5,7)}</text>`;});
 const values=points.filter(p=>p.value!==null).map(p=>p.value);return `<section class="panel individual-chart"><div class="panel-title"><h2>${label}</h2><span class="tag">${values.length} registos</span></div><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="${esc(label)}: ${points.map(p=>esc(p.s.date+': '+(p.value===null?'sem resposta':format(p.value)))).join('; ')}">${svg}</svg><div class="point-tooltip" role="status" hidden></div><p class="micro">Passa o cursor ou toca num ponto para ver o valor. As respostas em falta interrompem a linha.</p></section>`;
}
