 const id=ui.profilePlayer,teamId=ui.rosterTeam,sessions=playerSessions(teamId,id,$('profileFrom').value,$('profileTo').value,$('profileType').value),records=sessions.map(s=>s.records[id]||{}),wellness=records.map(wellnessTotal).filter(v=>v!==null),pse=records.filter(validPSE),loads=pse.map(loadValue);
 $('profileMetrics').innerHTML=metric(sessions.length,'Sessões como participante')+metric(format(mean(wellness),1),'Bem-estar médio','de 25 · '+wellness.length+' respostas')+metric(format(mean(pse.map(r=>r.pse)),1),'PSE média',pse.length+' respostas')+metric(format(loads.reduce((a,b)=>a+b,0)),'Carga acumulada · UA','PSE × minutos');
