 const indicator=ui.profileMetric||'sleep',metricInfo=METRICS.find(m=>m.id===indicator);$('profileCharts').insertAdjacentHTML('beforeend','<section class="panel indicator-picker"><label for="profileMetric">Indicador de bem-estar</label><select id="profileMetric">'+METRICS.map(m=>'<option value="'+m.id+'" '+(m.id===indicator?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></section>'+individualChart(sessions,id,'metric:'+indicator,metricInfo.name+' · 1–5',5,'#dfc08b'));$('profileMetric').onchange=()=>{ui.profileMetric=$('profileMetric').value;renderPlayerProfile();};
 wireChartPoints();
